"""
This module provides a semantic mapping of icon identifiers used throughout KivyDK. It exposes a single
:class:`Icon` namespace that groups Material Design Icons (MDI) codepoints into readable, IDE‑friendly
attribute names.

This improves readability, reduces the chance of mistakes when typing raw Unicode values and allows IDEs
to provide autocompletion for the full icon set.

.. note::
    The values defined in this module are Unicode codepoints from the Material Design Icons project.
    Additional icon groups will be added in the future as KivyDK expands its UI toolkit and this class
    will be rewritten from scratch.
"""
__all__ = ("Icon",)


#// LOGIC
class Icon:
    """
    Namespace containing Unicode codepoints for Material Design Icons (MDI).

    Each attribute in this class represents a single icon mapped to its corresponding Unicode
    character. The goal of this namespace is to provide readable, autocompletion‑friendly names
    for icons used throughout KivyDK, avoiding the need to manually reference raw codepoints.

    Example usage:
        ``label.text = Icon.Hand``
    """
